#!/usr/bin/env node
/**
 * Targeted R2 uploader: only push the 473 Hindi MP3s regenerated by
 * scripts/regen-hi-changed.cjs. PUT overwrites existing keys.
 *
 * Env vars required:
 *   CLOUDFLARE_API_TOKEN
 *   CLOUDFLARE_ACCOUNT_ID
 *   CF_BUCKET   (default: langlab-audio)
 */
const fs = require('fs');
const path = require('path');
const https = require('https');

const TOKEN = process.env.CLOUDFLARE_API_TOKEN;
const ACCT = process.env.CLOUDFLARE_ACCOUNT_ID;
// The public binding pub-fa9d7e83...r2.dev/quest-audio/<file> serves from
// THIS bucket with the quest-audio/ prefix; do NOT use langlab-audio (that
// bucket exists but is not served by the prod public URL).
const BUCKET = process.env.CF_BUCKET || 'langlab-srs-audio';
const KEY_PREFIX = process.env.CF_KEY_PREFIX || 'quest-audio/';
if (!TOKEN || !ACCT) {
  console.error('Set CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID');
  process.exit(1);
}

const CONCURRENCY = 16;
const AUDIO_DIR = path.resolve('public/quest-audio');

const CHANGED_IDS = fs.readFileSync('/tmp/hi-changed-ids.txt', 'utf8')
  .split('\n').map(s => s.trim()).filter(Boolean);
const files = CHANGED_IDS.map(id => `hi-${id}.mp3`);

// Verify all files exist locally
const missing = files.filter(f => !fs.existsSync(path.join(AUDIO_DIR, f)));
if (missing.length) {
  console.error(`Missing locally: ${missing.length}`);
  missing.slice(0, 5).forEach(m => console.error('  ' + m));
  process.exit(1);
}
const totalBytes = files.reduce((s, f) => s + fs.statSync(path.join(AUDIO_DIR, f)).size, 0);
console.log(`Uploading ${files.length} files (${(totalBytes/1024/1024).toFixed(1)} MB) → ${BUCKET}`);

const sleep = ms => new Promise(r => setTimeout(r, ms));

function uploadOne(filename) {
  return new Promise(resolve => {
    const filepath = path.join(AUDIO_DIR, filename);
    const stat = fs.statSync(filepath);
    const stream = fs.createReadStream(filepath);
    const req = https.request({
      hostname: 'api.cloudflare.com', port: 443, method: 'PUT',
      path: `/client/v4/accounts/${ACCT}/r2/buckets/${BUCKET}/objects/${encodeURI(KEY_PREFIX + filename)}`,
      headers: {
        Authorization: `Bearer ${TOKEN}`,
        'Content-Type': 'audio/mpeg',
        'Content-Length': stat.size,
      },
    }, res => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        if (res.statusCode === 200) return resolve({ ok: true });
        resolve({ ok: false, status: res.statusCode, body: body.slice(0, 200) });
      });
    });
    req.on('error', e => resolve({ ok: false, status: -1, body: e.message }));
    stream.pipe(req);
  });
}

async function withRetry(filename, max = 5) {
  for (let i = 0; i < max; i++) {
    const r = await uploadOne(filename);
    if (r.ok) return r;
    const wait = 500 * Math.pow(2, i) + Math.random() * 300;
    await sleep(wait);
  }
  return { ok: false };
}

(async () => {
  let done = 0, failed = 0, idx = 0;
  const t0 = Date.now();
  const failures = [];
  async function worker() {
    while (true) {
      const i = idx++;
      if (i >= files.length) return;
      const r = await withRetry(files[i]);
      if (r.ok) done++;
      else { failed++; failures.push({ file: files[i], ...r }); }
      const total = done + failed;
      if (total % 50 === 0 || total === files.length) {
        const dt = (Date.now() - t0) / 1000;
        console.log(`  ${total}/${files.length}  ✓${done} ✗${failed}  ${(total/dt).toFixed(1)}/s`);
      }
    }
  }
  await Promise.all(Array.from({length: CONCURRENCY}, () => worker()));
  console.log(`\nDone: ${done} ok, ${failed} failed in ${((Date.now()-t0)/1000).toFixed(1)}s`);
  if (failures.length) {
    fs.writeFileSync('/tmp/r2-hi-failures.json', JSON.stringify(failures, null, 2));
    console.log('Failures → /tmp/r2-hi-failures.json');
  }
})();
